using System.Text.Json;
using ChartForgeX.Interactivity;
using ChartForgeX.Interactivity.Html;
using ChartForgeX.Rendering;
using Microsoft.Playwright;
using Xunit;
using static ChartForgeX.Tests.InteractiveChartBrowser;

namespace ChartForgeX.Tests;

public sealed partial class NativeTransitionBrowserTests {
    [BrowserTheory] [InlineData("bubble", 390, false)] [InlineData("range", 760, true)] [InlineData("error", 390, false)] [InlineData("candlestick", 760, true)] [InlineData("ohlc", 390, false)]
    public async Task ActualRawComponentClipEntryKeepsNativeInkCatalogRegionsAcceptedSourceAndExports(string family, int width, bool dark) {
        if (!Enabled) return;
        var renderer = new HtmlInteractiveChartRenderer();
        HtmlChartSection Section(double value) => renderer.PrepareSection(NativeComponentClipBeforeControls.Model(family, value, width, dark), configure: options => { options.CaptureNativeValueSource = true; options.Interaction.ChartId = "native-clipped-components"; options.Interaction.Enable(ChartInteractionFeatures.Export); });
        var from = Section(120); var to = Section(40); var frames = VisualValueCapture.NativeFrames(from.PreparedVisual, to.PreparedVisual, 5, null); var payload = renderer.PrepareNativeTransitionJson(from, to, new HtmlNativeTransitionOptions(frameCount: 5)); var name = "clip-component-browser-" + family;
        await using var session = await BrowserProofFonts.OpenAsync(Page(from), width + 24, 680); var page = session.Page; await ReadyAndPauseAsync(page); await page.EmulateMediaAsync(new PageEmulateMediaOptions { ReducedMotion = ReducedMotion.NoPreference });
        await page.EvaluateAsync("()=>{window.clipChart=ChartForgeXCharts.get(document.querySelector('.cfx-interactive-chart'));window.clipRevision=clipChart.sceneRevision;window.clipEvents=[];clipChart.root.addEventListener('cfxupdated',event=>clipEvents.push(event.detail));}");
        var source = await page.EvaluateAsync<JsonElement>("()=>{const point=clipChart.root.querySelector('.cfx-stage>svg [data-cfx-role=point][data-cfx-observation-id=current]'),r=point.getBoundingClientRect();return {point:point.outerHTML,metadata:JSON.parse(clipChart.root.dataset.cfxPreparedChart),pointerInsidePoint:point.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2))}}");
        await page.EvaluateAsync("reply=>clipChart.update(reply.html,{sceneRevision:clipChart.sceneRevision,transition:reply.payload,motion:{duration:1000}})", new { html = to.Html, payload }); await page.Clock.RunForAsync(550);
        var observed = await page.EvaluateAsync<JsonElement>("family=>{const field=family==='range'?'cfxLower':family==='bubble'?'cfxY':family==='error'?'cfxValue':'cfxOpen',point=scope=>clipChart.root.querySelector(scope+' [data-cfx-role=point][data-cfx-observation-id=current]');return {before:clipRevision,revision:clipChart.sceneRevision,events:clipEvents,accepted:point('.cfx-stage>svg')?.dataset[field],transient:point('.cfx-native-motion-frame')?.dataset[field],catalog:[...clipChart.root.querySelectorAll('.cfx-stage>svg [data-cfx-role=point]')].map(row=>row.dataset.cfxObservationId),metadata:JSON.parse(clipChart.root.dataset.cfxPreparedChart),frame:clipChart.root.querySelector('.cfx-native-motion-frame')?.outerHTML}}", family);
        NativeRadialValueMotionTests.Capture(from, to, frames, payload, name); NativeRadialMotionBeforeControls.Save(name + ".observed.json", JsonSerializer.Serialize(new { source, observed }));
        if (Environment.GetEnvironmentVariable("CFX_BROWSER_CAPTURE_DIRECTORY") is { Length: > 0 } output) await page.ScreenshotAsync(new PageScreenshotOptions { Path = Path.Combine(output, name + ".browser.png"), FullPage = true });
        Assert.Equal(family == "range" ? "30" : "40", observed.GetProperty("accepted").GetString()); Assert.Equal(family == "range" ? "70" : "80", observed.GetProperty("transient").GetString()); Assert.Equal(1, observed.GetProperty("events").GetArrayLength()); Assert.NotEqual(observed.GetProperty("before").GetString(), observed.GetProperty("revision").GetString()); Assert.Equal(new[] { "current", "later" }, observed.GetProperty("catalog").EnumerateArray().Select(row => row.GetString())); if (family != "range") Assert.False(source.GetProperty("pointerInsidePoint").GetBoolean());
        await NativeValueFrameBrowserProof.AssertAsync(page, family == "range" ? "[data-cfx-role=range-area]" : "[data-cfx-role=point][data-cfx-observation-id=current]", name + "-ink", family is "candlestick" or "ohlc" or "error" ? .05 : .25);
        var download = await page.RunAndWaitForDownloadAsync(() => page.Locator("[data-cfx-export=svg]").ClickAsync()); var file = await download.PathAsync() ?? throw new InvalidOperationException("Native clipped accepted export missing."); var exported = await File.ReadAllTextAsync(file); NativeRadialMotionBeforeControls.Save(name + ".exported.svg", exported);
        var point = System.Xml.Linq.XDocument.Parse(exported).Descendants().Single(row => (string?)row.Attribute("data-cfx-role") == "point" && (string?)row.Attribute("data-cfx-observation-id") == "current"); Assert.Equal(family == "range" ? "30" : "40", point.Attribute(family == "range" ? "data-cfx-lower" : family == "bubble" ? "data-cfx-y" : family == "error" ? "data-cfx-value" : "data-cfx-open")!.Value);
        var destination = await page.EvaluateAsync<JsonElement>("()=>{const point=clipChart.root.querySelector('.cfx-stage>svg [data-cfx-role=point][data-cfx-observation-id=current]'),r=point.getBoundingClientRect();return {point:point.outerHTML,metadata:JSON.parse(clipChart.root.dataset.cfxPreparedChart),pointerInsidePoint:point.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2))}}"); NativeRadialMotionBeforeControls.Save(name + ".destination-hit.json", destination.GetRawText()); if (family != "range") Assert.True(destination.GetProperty("pointerInsidePoint").GetBoolean());
        Assert.Equal(0, await page.Locator(".cfx-native-motion-frame").CountAsync()); await page.EvaluateAsync("()=>clipChart.dispose()"); await page.Clock.RunForAsync(1500); Assert.Equal(0, await page.Locator(".cfx-native-motion-frame,[data-cfx-update-motion]").CountAsync()); AssertNoConsoleErrors(session);
    }
    [BrowserTheory] [InlineData(false)] [InlineData(true)]
    public async Task ActualClippedLogComponentsKeepIntrinsicPolicyAndRejectForgedZeroBeforeAcceptance(bool negative) {
        if (!Enabled) return;
        var renderer = new HtmlInteractiveChartRenderer(); var from = NativeComponentClipBeforeControls.Section(renderer, NativeComponentClipValueTests.Log(negative, negative ? -150 : 150)); var to = NativeComponentClipBeforeControls.Section(renderer, NativeComponentClipValueTests.Log(negative, negative ? -50 : 50)); var frames = VisualValueCapture.NativeFrames(from.PreparedVisual, to.PreparedVisual, 3, null); var payload = renderer.PrepareNativeTransitionJson(from, to, new HtmlNativeTransitionOptions(frameCount: 3));
        await using var session = await BrowserProofFonts.OpenAsync(Page(from), 784, 680); var page = session.Page; await ReadyAndPauseAsync(page);
        var observed = await page.EvaluateAsync<JsonElement>("reply=>{const chart=ChartForgeXCharts.get(document.querySelector('.cfx-interactive-chart')),p=JSON.parse(reply.payload),revision=chart.sceneRevision,source=chart.root.dataset.cfxPreparedChart,frame=p.drawings.wide.frames[1],svg=new DOMParser().parseFromString(frame.svg,'image/svg+xml'),point=svg.querySelector('[data-cfx-role=point][data-cfx-observation-id=current]');let events=0,error;chart.root.addEventListener('cfxupdated',()=>events++);frame.nativeValueSource.readings[0].value=0;point.setAttribute('data-cfx-y','0');frame.svg=svg.documentElement.outerHTML;try{chart.update(reply.html,{sceneRevision:revision,transition:JSON.stringify(p),motion:{duration:1000}})}catch(failure){error=failure.message}return {error,revisionUnchanged:chart.sceneRevision===revision,sourceUnchanged:chart.root.dataset.cfxPreparedChart===source,events,layers:chart.root.querySelectorAll('.cfx-native-motion-frame').length,payload:p}}", new { html = to.Html, payload });
        NativeRadialValueMotionTests.Capture(from, to, frames, payload, "clip-log-browser-" + negative); NativeRadialMotionBeforeControls.Save("clip-log-browser-" + negative + ".observed.json", observed.GetRawText()); if (Environment.GetEnvironmentVariable("CFX_BROWSER_CAPTURE_DIRECTORY") is { Length: > 0 } output) await page.ScreenshotAsync(new PageScreenshotOptions { Path = Path.Combine(output, "clip-log-browser-" + negative + ".browser.png"), FullPage = true });
        Assert.False(string.IsNullOrWhiteSpace(observed.GetProperty("error").GetString())); Assert.True(observed.GetProperty("revisionUnchanged").GetBoolean()); Assert.True(observed.GetProperty("sourceUnchanged").GetBoolean()); Assert.Equal(0, observed.GetProperty("events").GetInt32()); Assert.Equal(0, observed.GetProperty("layers").GetInt32());
        await page.EmulateMediaAsync(new PageEmulateMediaOptions { ReducedMotion = ReducedMotion.Reduce }); await page.EvaluateAsync("reply=>ChartForgeXCharts.get(document.querySelector('.cfx-interactive-chart')).update(reply.html,{transition:reply.payload})", new { html = to.Html, payload }); Assert.Equal(0, await page.Locator(".cfx-native-motion-frame").CountAsync()); AssertNoConsoleErrors(session);
    }
}
